export function initEarlyBuyers({quickAdd=async()=>{throw new Error('Smart wallets nejsou dostupné.');},isSaved=()=>false,toast=()=>{}}={}){
 const $=id=>document.getElementById(id),esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=value=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(Number(value)||0),short=value=>`${String(value||'').slice(0,6)}…${String(value||'').slice(-4)}`;
 let threshold=250,snapshotId=null,job=null,pollTimer=null,loading=false;
 const phaseOrder=['trending','pools','swaps','transfers','resolution','aggregation','saving','complete'];
 const phaseNames={trending:'Trending tokeny',pools:'Pool discovery',swaps:'Swap data',transfers:'Transfer data',resolution:'Wallet resolution',aggregation:'Agregace',saving:'Uložení snapshotu',complete:'Hotovo'};
 async function api(path,options={}){const response=await fetch('/api/early-buyers'+path,{credentials:'same-origin',...options,headers:{Accept:'application/json',...(options.body?{'Content-Type':'application/json'}:{}),...(options.headers||{})}});const body=await response.json().catch(()=>({}));if(!response.ok)throw Object.assign(new Error(body.error||'Early Buyers není dostupné.'),{status:response.status,code:body.code});return body;}
 function date(value,withTime=true){if(!value)return '—';return new Intl.DateTimeFormat('cs-CZ',{dateStyle:'medium',...(withTime?{timeStyle:'short'}:{})}).format(new Date(value));}
 function duration(value){const seconds=Math.max(0,Math.round((Number(value)||0)/1000));return seconds<60?`${seconds} s`:`${Math.floor(seconds/60)} min ${String(seconds%60).padStart(2,'0')} s`;}
 function renderProgress(){const box=$('early-buyers-progress');if(!box)return;const active=job?.status==='running';box.hidden=!active&&job?.status!=='failed';if(box.hidden)return;
  $('early-progress-title').textContent=job?.status==='failed'?'Scan se nepodařilo dokončit':job?.phaseLabel||phaseNames[job?.phase]||'Příprava scanu…';$('early-progress-token').textContent=job?.tokenProgress?`Token ${job.tokenProgress}`:'';
  $('early-progress-steps').innerHTML=phaseOrder.slice(0,7).map((phase,index)=>{const current=phaseOrder.indexOf(job?.phase||'trending');const state=phase===job?.phase?'active':index<current?'done':'';return `<span class="early-progress-step ${state}"><i>${state==='done'?'✓':index+1}</i>${phaseNames[phase]}</span>`;}).join('');
  $('early-progress-error').textContent=job?.error||'';$('early-progress-error').hidden=!job?.error;$('early-return-running').hidden=!active;
  document.querySelectorAll('[data-early-start]').forEach(button=>{button.disabled=active||loading;button.innerHTML=active?'<span class="spinner"></span> Scan běží…':'Spustit nový scan';});
 }
 function renderHistory(items=[]){$('early-buyers-history-list').innerHTML=items.length?items.map(item=>`<div class="early-history-row"><button type="button" class="early-history-open" data-early-snapshot="${esc(item.id)}"><strong>${date(item.capturedAt)}</strong><span>${item.analyzedTokenCount} / ${item.trendingCount} tokenů · ${item.confirmedWalletCount} wallets · ${duration(item.durationMs)} · Top 100 ${item.excludeTop100?'vyloučen':'zahrnut'}</span><small class="early-status ${esc(item.status)}">${item.status==='complete_with_warnings'?'Dokončeno s upozorněním':item.status==='complete'?'Dokončeno':item.status==='running'?'Běží':'Selhalo'}</small></button><button type="button" class="early-history-delete" data-early-delete="${esc(item.id)}" ${item.status==='running'?'disabled':''} aria-label="Smazat snapshot ${date(item.capturedAt)}" title="Smazat snapshot">×</button></div>`).join(''):'<p class="early-buyers-empty-inline">Zatím nejsou uložené žádné snapshoty.</p>';}
 function renderWallets(wallets=[]){$('early-buyers-wallet-count').textContent=String(wallets.length);$('early-buyers-no-wallets').hidden=!!wallets.length;$('early-buyers-wallets').innerHTML=wallets.map(wallet=>{
  const chips=wallet.tokens.map(token=>`<span class="early-token-chip ${token.isCurrent?'current':''}" title="${esc(token.chain)} · ${esc(token.contract)}&#10;First buy: ${esc(date(token.firstBuyAt))}&#10;Last buy: ${esc(date(token.lastBuyAt))}&#10;${token.buyCount} nákupů · ${money(token.totalUsdBought)} · lead ${Number(token.leadTimeHours).toFixed(1)} h">${esc(token.symbol)}</span>`).join('');
  const chains=[...new Set(wallet.tokens.map(token=>token.chain))],saved=isSaved(wallet.wallet),title=saved?'Již ve Smart wallets':'Přidat do Smart wallets · Kandidát · research';
  return `<tr><td class="early-wallet-cell"><button type="button" class="early-wallet-open" data-wallet="${esc(wallet.wallet)}" title="Otevřít canonical wallet detail">${esc(short(wallet.wallet))}</button><small>${esc(wallet.wallet)}</small></td><td><strong class="early-historical-hit">${wallet.historicalHits}</strong></td><td>${wallet.currentHits}</td><td><div class="early-token-chips">${chips||'—'}</div></td><td>${money(wallet.totalUsdBought)}</td><td>${Number(wallet.avgLeadHours||0).toFixed(1)} h</td><td>${date(wallet.lastHitAt)}</td><td><button type="button" class="early-quick-add ${saved?'saved':''}" data-early-add="${esc(wallet.wallet)}" data-early-chains="${esc(chains.join(','))}" title="${title}" aria-label="${title} ${esc(short(wallet.wallet))}" ${saved?'disabled':''}>${saved?'✓':'+'}</button></td></tr>`;
 }).join('');}
 function renderCoverage(items=[]){const status={analyzed:'Analyzováno',excluded_top_100:'Top 100 market cap',non_evm:'Non-EVM',unsupported_chain:'Nepodporovaný chain',no_contract:'Bez contractu',low_liquidity:'Nízká likvidita',unsupported_dex:'Unsupported DEX',failed:'Failed'};$('early-buyers-coverage').innerHTML=items.map(token=>{const pool=token.pools?.[0]||token,rank=Number.isInteger(token.marketCapRank)?`Market cap #${token.marketCapRank}`:'Market cap rank: —';return `<tr><td>#${token.rank}</td><td><strong>${esc(token.symbol)}</strong><small>${esc(token.id)}</small><small>${rank}</small></td><td>${esc(token.chain||'—')}</td><td title="${esc(token.skipReason||'')}">${esc(pool.dexId||'—')}</td><td>${money(pool.liquidityUsd||0)}</td><td><span class="early-status ${esc(token.status)}">${esc(status[token.status]||token.status)}</span>${token.skipReason?`<small class="early-skip-reason">${esc(token.skipReason)}</small>`:''}</td></tr>`;}).join('')||'<tr><td colspan="6">Coverage není k dispozici.</td></tr>';}
 function renderDiagnostics(snapshot){const timings=snapshot.phaseTimings||{},diag=snapshot.diagnostics||{};$('early-buyers-diagnostics-content').innerHTML=`<div class="early-diagnostics-meta"><span>Snapshot: ${date(snapshot.capturedAt)}</span><span>Window: ${date(snapshot.windowStart,false)} – ${date(snapshot.windowEnd,false)}</span><span>Status: ${esc(snapshot.status)}</span><span>Market-cap Top 100: ${snapshot.excludeTop100?'vyloučen':'zahrnut'}</span><span>Runtime: ${duration(snapshot.durationMs)}</span></div><div class="early-diagnostics-grid">${[['CoinGecko',timings.coingeckoMs],['DEX Screener',timings.dexMs],['Block range',timings.blockRangeResolutionMs],['Swap query',timings.swapQueryMs],['Transfer query',timings.transferQueryMs],['TX metadata',timings.txMetadataMs],['Pricing',timings.pricingMs],['Wallet resolution',timings.walletResolutionMs],['Aggregation',timings.aggregationMs]].map(([name,value])=>`<span>${name}<b>${duration(value)}</b></span>`).join('')}</div><p>${Number(snapshot.queryCount)||0} HyperSync queries · ${Number(snapshot.responsePages)||0} response pages · ${Number(snapshot.responseBytes||0).toLocaleString('en-US')} response bytes · ${Number(snapshot.swapLogCount||0).toLocaleString('en-US')} Swap logs · ${Number(snapshot.transferLogCount||0).toLocaleString('en-US')} Transfer logs · ${Number(snapshot.candidateBuyCount||0).toLocaleString('en-US')} candidates · ${Number(snapshot.confirmedBuyCount||0).toLocaleString('en-US')} confirmed · ${Number(snapshot.uncertainCount||0).toLocaleString('en-US')} uncertain · ${Number(snapshot.unpricedCount||0).toLocaleString('en-US')} unpriced.</p><p>Produkční scan nevolá Blockscout validation. UNVERIFIED vzorky nejsou INVALID.</p>${snapshot.errorSummary?`<p class="error-message">${esc(snapshot.errorSummary)}</p>`:''}`;}
 function render(result){const empty=!result.snapshot;$('early-buyers-empty').hidden=!empty;$('early-buyers-results').hidden=empty;if(empty){renderHistory(result.history||[]);renderProgress();return;}
  const snapshot=result.snapshot,summary=result.summary||{};snapshotId=snapshot.id;$('early-buyers-freshness').innerHTML=`Snapshot <strong>${date(snapshot.capturedAt)}</strong> · nákupy ${date(snapshot.windowStart,false)} až ${date(snapshot.windowEnd,false)} · <span class="early-status ${esc(snapshot.status)}">${snapshot.status==='complete_with_warnings'?'s upozorněním':'uložen'}</span>`;
  $('early-buyers-summary').innerHTML=`<article><span>Analyzováno</span><strong>${snapshot.analyzedTokenCount} / ${snapshot.trendingCount}</strong><small>CoinGecko Trending</small></article><article><span>Confirmed early buyers</span><strong>${summary.confirmedEarlyBuyers||0}</strong><small>Threshold $${threshold}+</small></article><article class="historical-card"><span>Historical repeaters</span><strong>${summary.historicalRepeaters||0}</strong><small>Wallets s alespoň 2 různými tokeny</small></article><article><span>Avg lead</span><strong>${summary.avgLeadHours===null||summary.avgLeadHours===undefined?'—':`${Number(summary.avgLeadHours).toFixed(1)} h`}</strong><small>Podle distinct tokenů na wallet</small></article>`;
  document.querySelectorAll('[data-early-threshold]').forEach(button=>{const active=Number(button.dataset.earlyThreshold)===threshold;button.setAttribute('aria-pressed',String(active));button.classList.toggle('active',active);});
  renderWallets(result.wallets||[]);renderCoverage(result.coverage||[]);renderHistory(result.history||[]);renderDiagnostics(snapshot);renderProgress();
 }
 async function load({selected=snapshotId}={}){if(loading)return;loading=true;try{const query=new URLSearchParams({threshold:String(threshold)});if(selected)query.set('snapshot',selected);const result=await api('?'+query.toString());render(result);}catch(error){$('early-buyers-empty').hidden=false;$('early-buyers-empty-error').textContent=error.message;$('early-buyers-empty-error').hidden=false;}finally{loading=false;renderProgress();}}
 async function refreshJob(){try{const result=await api('/status');job=result.job;if(job?.status==='running'){renderProgress();return;}clearInterval(pollTimer);pollTimer=null;if(job){renderProgress();await load({selected:snapshotId});}}catch{}}
 function beginPolling(){if(pollTimer)clearInterval(pollTimer);pollTimer=setInterval(refreshJob,1400);refreshJob();}
 async function start(){if(loading||job?.status==='running')return;loading=true;snapshotId=null;document.querySelectorAll('[data-early-start]').forEach(button=>{button.disabled=true;button.textContent='Spouštím scan…';});try{const result=await api('/scan',{method:'POST',body:JSON.stringify({excludeTop100:$('early-buyers-exclude-top-100').checked})});job=result.job;renderProgress();beginPolling();}catch(error){$('early-buyers-empty-error').textContent=error.message;$('early-buyers-empty-error').hidden=false;$('early-progress-error').textContent=error.message;$('early-progress-error').hidden=false;if(error.code==='missing_envio_token'){$('early-buyers-empty').hidden=false;$('early-buyers-results').hidden=true;}toast(error.message);}finally{loading=false;renderProgress();}}
 async function chooseThreshold(value){threshold=Number(value);if(![250,500].includes(threshold))return;await load();}
 async function removeSnapshot(id){if(!globalThis.confirm?.('Smazat tento Early Buyers snapshot a jeho agregovaná data? Smart wallets ani jiné snapshoty se nezmění.'))return;try{await api(`/snapshots/${encodeURIComponent(id)}`,{method:'DELETE'});if(snapshotId===id)snapshotId=null;await load({selected:null});toast('Snapshot byl smazán.');}catch(error){toast(error.message);}}
 document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;if(button.matches('[data-early-start]')){start();return;}if(button.dataset.earlyThreshold){chooseThreshold(button.dataset.earlyThreshold);return;}if(button.dataset.earlySnapshot){load({selected:button.dataset.earlySnapshot});return;}if(button.dataset.earlyDelete){removeSnapshot(button.dataset.earlyDelete);return;}if(button.dataset.earlyAdd){const address=button.dataset.earlyAdd,chains=button.dataset.earlyChains.split(',').filter(Boolean);button.disabled=true;button.textContent='…';Promise.resolve(quickAdd(address,chains)).then(result=>{button.classList.add('saved');button.textContent='✓';button.title='Uloženo ve Smart wallets jako Kandidát · research';toast(result?.created?'Přidáno do Smart wallets.':'Wallet už je ve Smart wallets.');}).catch(error=>{button.disabled=false;button.textContent='+';toast(error.message||'Quick-add se nepodařil.');});return;}if(button.id==='early-return-running')$('early-buyers-progress').scrollIntoView({behavior:'smooth',block:'center'});});
 return {async show(){const [result]=await Promise.allSettled([load(),refreshJob()]);return result;},refresh:load,close(){if(pollTimer)clearInterval(pollTimer);pollTimer=null;}};
}
